  "Bu ülkede (${destCurrencyCode}) kredi kartı kullanırken POS cihazı size \"TL ile mi yoksa ${destCurrencyCode} ile mi ödemek istersiniz?\" diye sorarsa MUTLAKA YEREL PARA BİRİMİNİ (${destCurrencyCode}) SEÇİN! \"TL ile öde\" seçeneği (DCC), bankanız yerine yerel işletmenin ve aracı POS terminalinin %5 ila %12 arasında fahiş kur marjı kesmesine neden olur. ATM'lerde de nakit çekerken daima \"Without Conversion\" (Dönüştürmesiz) seçeneğini tercih edin.": "Ao pagar com cartão neste país, sempre escolha a moeda LOCAL (${destCurrencyCode}) na maquininha, se perguntarem. Escolher a moeda do seu país ativa a DCC (conversão dinâmica de moeda), com margens ocultas de 5 a 12%! Ao sacar dinheiro em caixas eletrônicos, sempre escolha \"Sem conversão\".",
  "When paying by card in this country, always choose the LOCAL currency (${destCurrencyCode}) on the terminal if asked. Selecting your home currency triggers DCC (Dynamic Currency Conversion) with 5-12% hidden markup fees! When withdrawing from ATMs, always pick \"Without Conversion\".": "Ao pagar com cartão neste país, sempre escolha a moeda LOCAL (${destCurrencyCode}) na maquininha, se perguntarem. Escolher a moeda do seu país ativa a DCC (conversão dinâmica de moeda), com margens ocultas de 5 a 12%! Ao sacar dinheiro em caixas eletrônicos, sempre escolha \"Sem conversão\".",
