  "Tüm kayıtlı seyahatleriniz, rotalarınız ve kontrol listeleriniz bu cihazdan silinecektir. Onaylıyor musunuz?": "Todas as suas viagens, roteiros e checklists de preparação salvos serão apagados permanentemente deste dispositivo. Tem certeza?",
