  "Türk pasaportu için her ülke kartında özel doğrulama durumu (3 veri seti mutabık / resmi kaynak teyidi bekliyor) gösterilir.": "Cada cartão de destino traz selos de auditoria que indicam consenso entre 3 bases de dados ou circulares diplomáticas pendentes.",
  "Every destination card features audit badges indicating consensus across 3 datasets or pending diplomatic circulars.": "Cada cartão de destino traz selos de auditoria que indicam consenso entre 3 bases de dados ou circulares diplomáticas pendentes.",
  "Karadağ Kural Bildirimi:": "Transição de Montenegro em 2026:",
  "Montenegro 2026 Transition:": "Transição de Montenegro em 2026:",
  "31 Ekim 2026'ya kadar 30 gün vizesiz; 1 Kasım 2026 itibarıyla vize zorunluluğu sisteme işlenmiştir.": "Permanência sem visto permitida até 31 de outubro de 2026; visto obrigatório a partir de 1º de novembro de 2026.",
  "Visa-free stay permitted through Oct 31, 2026; mandatory visa regime effective starting Nov 1, 2026.": "Permanência sem visto permitida até 31 de outubro de 2026; visto obrigatório a partir de 1º de novembro de 2026.",
  "Tayland Güncellemesi:": "Regras de entrada na Tailândia:",
  "Thailand Entry Guidelines:": "Regras de entrada na Tailândia:",
  "15 Eylül 2026 tarihli 30 gün kuralı ve TDAC dijital varış kartı yönergesi eklenmiştir.": "Reflete a isenção padrão de 30 dias e as diretrizes do portal eletrônico de chegada TDAC.",
  "Reflects the standard 30-day exemption and TDAC electronic arrival portal directives.": "Reflete a isenção padrão de 30 dias e as diretrizes do portal eletrônico de chegada TDAC.",
  "Yasal Uyarı & Sorumluluk Reddi (Disclaimer)": "Isenção de responsabilidade e aviso não vinculante",
  "Legal Disclaimer & Non-Binding Notice": "Isenção de responsabilidade e aviso não vinculante",
  "Bu uygulama yalnızca kişisel seyahat planlama, rota analizi ve genel bilgilendirme amacıyla hazırlanmıştır. Ülkelerin vize rejimleri, e-vize kuralları, transit geçiş şartları ve sınır kabul koşulları mütekabiliyet ve ikili anlaşmalara bağlı olarak anlık değişebilmektedir. Nihai ve bağlayıcı bilgi için seyahat öncesinde mutlaka ilgili ülkenin diplomatik misyonu (Büyükelçilik/Başkonsolosluk) veya T.C. Dışişleri Bakanlığı resmi kaynaklarından teyit alınız.": "Este aplicativo é oferecido exclusivamente para planejamento de viagens pessoais, simulação de rotas e consulta de informações gerais. As regras nacionais de visto, as exigências de e-Visa, as isenções de visto de trânsito e os requisitos de entrada na fronteira podem mudar sem aviso prévio por causa de tratados bilaterais e regras de reciprocidade. Antes de embarcar, sempre confirme os requisitos definitivos diretamente com as representações diplomáticas (embaixadas/consulados) ou nos portais oficiais de imigração do governo.",
  "This application is provided exclusively for personal travel planning, route simulation and general informational reference. National visa regulations, eVisa mandates, transit visa exemptions, and border entry requirements can change without prior warning due to bilateral treaties and reciprocity rules. Always confirm final binding requirements directly with diplomatic missions (Embassies/Consulates) or official government immigration portals before embarking.": "Este aplicativo é oferecido exclusivamente para planejamento de viagens pessoais, simulação de rotas e consulta de informações gerais. As regras nacionais de visto, as exigências de e-Visa, as isenções de visto de trânsito e os requisitos de entrada na fronteira podem mudar sem aviso prévio por causa de tratados bilaterais e regras de reciprocidade. Antes de embarcar, sempre confirme os requisitos definitivos diretamente com as representações diplomáticas (embaixadas/consulados) ou nos portais oficiais de imigração do governo.",
  "Gizlilik Politikası & KVKK / GDPR Uyumu": "Arquitetura de privacidade e conformidade com GDPR/KVKK",
  "Privacy Architecture & GDPR / KVKK Compliance": "Arquitetura de privacidade e conformidade com GDPR/KVKK",
  "VizeRehberi uygulaması %100 istemci tarafında (Client-Side) çalışır. Kaydettiğiniz seyahat tarihleri, duraklar, seçtiğiniz vatandaşlıklar ve hazırlık kontrol listesi kutuları yalnızca tarayıcınızın yerel hafızasında (LocalStorage) şifresiz ve anonim olarak saklanır. Hiçbir kişisel veri uzak bir sunucuya iletilmez, analiz şirketleriyle paylaşılmaz veya satılmaz.": "Este aplicativo web funciona 100% no lado do cliente (no seu navegador). As datas de viagem, roteiros, cidadania selecionada e itens do checklist de preparação ficam armazenados exclusivamente no LocalStorage do seu navegador. Nenhum dado pessoal é enviado a servidores de telemetria externos, compartilhado com anunciantes ou armazenado em bancos de dados remotos.",
  "This web application operates 100% on the client side (in your local browser). Your logged trip dates, itineraries, selected citizenship, and preparation checklist items are stored strictly in your browser LocalStorage. No personal data is transmitted to external telemetry servers, shared with advertisers, or stored in remote databases.": "Este aplicativo web funciona 100% no lado do cliente (no seu navegador). As datas de viagem, roteiros, cidadania selecionada e itens do checklist de preparação ficam armazenados exclusivamente no LocalStorage do seu navegador. Nenhum dado pessoal é enviado a servidores de telemetria externos, compartilhado com anunciantes ou armazenado em bancos de dados remotos.",
