  "Global Digital Nomad & Easy Living Hubs (2026)": "Nômades digitais pelo mundo e destinos com vida fácil (2026)",
  "Tayland, Bali, Da Nang gibi popüler ve ultra ekonomik merkezlerden Avrupa ve Latin Amerika'ya kadar kolay ikamet, sıfır vergi ve hızlı vize imkanı sunan ${NOMAD_HUBS.length} küresel göçebe rotası.": "De destinos nômades populares e ultrabaratos como Tailândia, Bali e Da Nang até a Europa e as Américas, explore ${NOMAD_HUBS.length} destinos nômades no mundo todo, com vistos simplificados e regimes fiscais favoráveis.",
  "From popular, ultra-economic nomad hotspots like Thailand, Bali, and Da Nang to Europe and the Americas, explore ${NOMAD_HUBS.length} global nomad destinations with streamlined visas and favorable tax regimes.": "De destinos nômades populares e ultrabaratos como Tailândia, Bali e Da Nang até a Europa e as Américas, explore ${NOMAD_HUBS.length} destinos nômades no mundo todo, com vistos simplificados e regimes fiscais favoráveis.",
