  "Resmi Başvuru Sitesi": "Portal oficial",
  "183 Gün Kuralı & Vergi Mukimliği Takibi": "Monitor de residência fiscal e regra dos 183 dias",
  "183-Day Rule & Tax Residency Monitor": "Monitor de residência fiscal e regra dos 183 dias",
  "OECD ve uluslararası vergi hukuku uyarınca, bir ülkede tek bir takvim yılı içinde (1 Ocak – 31 Aralık) kesintisiz veya aralıklı olarak 183 günden fazla bulunursanız, o ülkenin tam mükellef vergi mukimi haline gelebilir ve dünya geneli gelirleriniz üzerinden vergilendirilme riskiyle karşılaşabilirsiniz.": "Segundo as diretrizes da OCDE e os tratados fiscais internacionais, passar mais de 183 dias em uma mesma jurisdição dentro de um ano-calendário (de 1º de janeiro a 31 de dezembro) pode gerar residência fiscal, sujeitando sua renda mundial aos impostos locais.",
  "Under OECD guidelines and international tax conventions, spending more than 183 days within a single calendar year (Jan 1 – Dec 31) in a jurisdiction may trigger tax residency, exposing worldwide income to local taxation.": "Segundo as diretrizes da OCDE e os tratados fiscais internacionais, passar mais de 183 dias em uma mesma jurisdição dentro de um ano-calendário (de 1º de janeiro a 31 de dezembro) pode gerar residência fiscal, sujeitando sua renda mundial aos impostos locais.",
  "Vergi Mukimliğine Girmeden Seyahat Taktikleri": "Dicas de planejamento tributário para nômades",
  "Nomad Tax Planning Tips": "Dicas de planejamento tributário para nômades",
  "• Bir takvim yılında hiçbir yabancı ülkede 180 günden fazla kalmamaya özen gösterin.": "• Controle com cuidado os seus dias de permanência e evite passar de 180 dias por ano em qualquer jurisdição estrangeira.",
  "• Monitor stay days carefully and avoid exceeding 180 days in any foreign jurisdiction per year.": "• Controle com cuidado os seus dias de permanência e evite passar de 180 dias por ano em qualquer jurisdição estrangeira.",
  "• Şirket veya serbest meslek kazançlarınız için Türkiye veya Gürcistan gibi vergi mukimliği merkezinizde vergi ödediğinizi kanıtlayan Mukimlik Belgesi (Certificate of Tax Residence) edinin.": "• Tenha um Certificado de Residência Fiscal formal do seu país de origem ou da base escolhida (por exemplo, Turquia, Geórgia).",
  "• Maintain a formal Certificate of Tax Residence from your primary home country or chosen base (e.g. Turkey, Georgia).": "• Tenha um Certificado de Residência Fiscal formal do seu país de origem ou da base escolhida (por exemplo, Turquia, Geórgia).",
  "• Çifte Vergilendirmeyi Önleme Anlaşmaları (ÇVÖA) haklarınızı korumak için seyahat tarihlerinizi ve uçuş biniş kartlarınızı arşivleyin.": "• Guarde os cartões de embarque e os carimbos do passaporte para comprovar os direitos previstos nos Acordos para Evitar a Dupla Tributação (DTAA).",
  "• Keep airline boarding passes and passport stamps logged to substantiate treaty rights under Double Taxation Avoidance Agreements (DTAA).": "• Guarde os cartões de embarque e os carimbos do passaporte para comprovar os direitos previstos nos Acordos para Evitar a Dupla Tributação (DTAA).",
  "Bu Yılki Seyahatleriniz ve Mukimlik Sınırına Kalan Günler (${new Date().getFullYear()})": "Viagens deste ano e dias restantes até o limite de 183 dias (${new Date().getFullYear()})",
  "Trips This Year & Days Remaining Before 183-Day Threshold (${new Date().getFullYear()})": "Viagens deste ano e dias restantes até o limite de 183 dias (${new Date().getFullYear()})",
  "Kalan Gün Sayacı veya Rota sekmelerinde ülke bazlı henüz seyahat kaydı bulunmuyor. Seyahat ekledikçe vergi gün sayacı burada otomatik belirecektir.": "Nenhuma viagem registrada ainda. Conforme você registrar viagens na aba Schengen & Stay Tracker, os contadores de situação fiscal vão aparecer aqui automaticamente.",
  "No trip records logged yet. As you record trips in the Schengen & Stay Tracker tab, tax status counters will appear here automatically.": "Nenhuma viagem registrada ainda. Conforme você registrar viagens na aba Schengen & Stay Tracker, os contadores de situação fiscal vão aparecer aqui automaticamente.",
