  "İki kıtayı birleştiren metropol İstanbul’dan başlayıp peri bacalarıyla büyüleyen Kapadokya’ya, antik Ege mirası Efes’ten Akdeniz’in berrak sularına uzanan 11 günlük eksiksiz bir Türkiye keşfi.": "Uma viagem clássica de 11 dias pela Turquia: começa na transcontinental Istambul, sobrevoa as chaminés de fada da Capadócia, explora a antiga Éfeso e termina relaxando no litoral turquesa do Mediterrâneo.",
  "An 11-day quintessential Turkish voyage starting in transcontinental Istanbul, flying over Cappadocia fairy chimneys, exploring ancient Ephesus, and relaxing along Mediterranean Turquoise shores.": "Uma viagem clássica de 11 dias pela Turquia: começa na transcontinental Istambul, sobrevoa as chaminés de fada da Capadócia, explora a antiga Éfeso e termina relaxando no litoral turquesa do Mediterrâneo.",
