  "Geleceğin neon ışıklı metropolü Tokyo’dan başlayıp Fuji Dağı eteklerindeki kaplıcalara, Kyoto’nun bin yıllık Zen tapınaklarından Osaka’nın efsanevi sokak lezzetlerine uzanan 10 günlük kusursuz rota.": "Um roteiro de 10 dias de nível magistral que une a hipermoderna Tóquio, as águas termais de Hakone com vista para o Fuji, os santuários milenares de Kyoto, os cervos que fazem reverência em Nara e as delícias gastronômicas de Osaka.",
