  "⚠️ ÖLÜMCÜL TEHLİKE: Reynisfjara kumsalında denize ASLA sırtınızı dönmeyin! Aniden kıyıya vuran devasa sinsi dalgalar (sneaker waves) insanları okyanusa çekip boğmaktadır. Kırmızı uyarı ışığına kesinlikle uyun.": "⚠️ PERIGO EXTREMO: nunca dê as costas para o mar em Reynisfjara! As chamadas sneaker waves (ondas traiçoeiras) avançam de forma imprevisível e arrastam pessoas para o oceano gelado. Respeite rigorosamente as luzes de alerta.",
  "⚠️ EXTREME DANGER: Never turn your back to the sea at Reynisfjara! Sneaker waves strike unpredictably and pull people into the freezing ocean. Obey warning lights strictly.": "⚠️ PERIGO EXTREMO: nunca dê as costas para o mar em Reynisfjara! As chamadas sneaker waves (ondas traiçoeiras) avançam de forma imprevisível e arrastam pessoas para o oceano gelado. Respeite rigorosamente as luzes de alerta.",
  "Şelalelerin yanına giderken su geçirmez ceket ve pantolon şarttır; dakikalar içinde sırılsıklam olursunuz.": "Use camadas externas totalmente impermeáveis nas cachoeiras, ou você ficará encharcado em segundos.",
