  "Skyr": "Skyr",
  "İzlanda’da bahşiş kültürü yoktur; vergiler ve hizmet bedelleri fiyata tamamen dahildir. Çeşme suyu dünyanın en temiz buzul suyudur; asla şişe su satın almayın, mataranızı musluktan doldurun.": "Gorjeta não é esperada nem necessária em nenhum lugar da Islândia. A água da torneira está entre as mais puras do mundo; nunca compre água engarrafada.",
  "Tipping is not expected or necessary anywhere in Iceland. Tap water is among the purest in the world; never buy bottled water.": "Gorjeta não é esperada nem necessária em nenhum lugar da Islândia. A água da torneira está entre as mais puras do mundo; nunca compre água engarrafada.",
