  "İzlanda’da off-road (yol dışı) araç kullanmak kesinlikle yasaktır ve doğaya verilen kalıcı zarar nedeniyle astronomik para cezası uygulanır.": "Dirigir fora das estradas é totalmente ilegal na Islândia e rende multas enormes, para proteger o musgo, que é muito frágil.",
  "Off-road driving is strictly illegal in Iceland and carries massive fines to protect delicate moss.": "Dirigir fora das estradas é totalmente ilegal na Islândia e rende multas enormes, para proteger o musgo, que é muito frágil.",
  "Hava aniden değişebilir; kapı açarken aracın kapısını iki elinizle tutun, şiddetli fırtınalarda kapılar ters dönebilir.": "Segure a porta do carro com as duas mãos ao abrir; rajadas de vento extremas costumam arrancar as portas das dobradiças.",
  "Hold car doors with both hands when opening; extreme wind gusts frequently rip car doors off hinges.": "Segure a porta do carro com as duas mãos ao abrir; rajadas de vento extremas costumam arrancar as portas das dobradiças.",
  "Ülkede organize suç veya taksi dolandırıcılığı yoktur; en büyük tehlike ekstrem doğa koşullarıdır.": "Praticamente não há crimes violentos; os perigos naturais e o clima são suas únicas preocupações de segurança.",
  "There is virtually zero violent crime; natural hazards and weather are your only safety concerns.": "Praticamente não há crimes violentos; os perigos naturais e o clima são suas únicas preocupações de segurança.",
  "Almanya Masal & Tarih Rotası: Berlin, Romantik Yol & Bavyera Alpleri": "Alemanha de conto de fadas e patrimônio: Berlim, a Rota Romântica e os Alpes da Baviera",
