  "İran’da yemekler son derece doyurucu ve aromatiktir. Restoranlarda servis personeline %10 civarında nakit bahşiş bırakmak büyük nezaket sayılır. Alışverişlerde esnafın ilk teklifte ücreti reddettiği \"Taarof\" jestiyle karşılaşıldığında her zaman ısrarla ödeme yapılmalıdır.": "A cozinha persa é rica, aromática e reconfortante. Deixe cerca de 10% de gorjeta em dinheiro por um bom atendimento. Se o comerciante fizer o ritual do \"taarof\" (recusar educadamente o pagamento no início), sempre insista com educação em pagar.",
  "Persian cuisine is rich, aromatic, and comforting. Leave around 10% cash gratuity for good service. If merchants engage in the \"Taarof\" ritual (politely declining payment at first), always insist politely on paying.": "A cozinha persa é rica, aromática e reconfortante. Deixe cerca de 10% de gorjeta em dinheiro por um bom atendimento. Se o comerciante fizer o ritual do \"taarof\" (recusar educadamente o pagamento no início), sempre insista com educação em pagar.",
  "DİKKAT: Yeterli miktarda nakit USD veya EUR (Uluslararası banka kartları yaptırımlar sebebiyle çalışmaz)": "IMPORTANTE: dinheiro suficiente em USD ou EUR (cartões bancários internacionais não funcionam por causa das sanções)",
  "CRITICAL: Sufficient cash in USD or EUR (International bank cards do not work due to sanctions)": "IMPORTANTE: dinheiro suficiente em USD ou EUR (cartões bancários internacionais não funcionam por causa das sanções)",
  "Kamuya açık alanlar için kıyafet kuralına uygun giysiler (kadınlar için başörtüsü/şal ve dökümlü kıyafet, erkekler için pantolon)": "Roupas discretas que respeitem o código de vestimenta local (lenço na cabeça e túnica larga para mulheres, calça comprida para homens)",
  "Modest clothing complying with local dress codes (Headscarf & loose tunic for women, trousers for men)": "Roupas discretas que respeitem o código de vestimenta local (lenço na cabeça e túnica larga para mulheres, calça comprida para homens)",
