  "Paranızı sokaktaki komisyonculardan değil, yalnızca cadde üzerindeki resmi \"Sarrafi\" döviz bürolarında bozdurun.": "Troque dinheiro apenas nas casas de câmbio oficiais autorizadas (sarrafi), nunca com cambistas de rua.",
  "Only exchange money at licensed official Sarrafi exchange offices, never with street touts.": "Troque dinheiro apenas nas casas de câmbio oficiais autorizadas (sarrafi), nunca com cambistas de rua.",
  "Kamu binaları, askeri tesisler, elçilikler ve köprülerin fotoğrafını kesinlikle çekmeyin.": "Nunca fotografe prédios do governo, áreas militares, postos de controle ou pontes.",
  "Never photograph government buildings, military sites, checkpoints, or bridges.": "Nunca fotografe prédios do governo, áreas militares, postos de controle ou pontes.",
  "Halk son derece misafirperverdir; ikramları ve sıcak sohbetleri güvenle kabul edebilirsiniz.": "Os moradores são extremamente calorosos e acolhedores; participe com educação das conversas e dos convites para um chá.",
  "Locals are exceptionally warm and welcoming; engage politely in conversation and tea invitations.": "Os moradores são extremamente calorosos e acolhedores; participe com educação das conversas e dos convites para um chá.",
  "Evlere ve camilere girerken ayakkabılar mutlaka çıkarılır.": "É preciso tirar os sapatos antes de entrar em casas e mesquitas.",
  "Shoes must be removed before entering homes and mosques.": "É preciso tirar os sapatos antes de entrar em casas e mesquitas.",
  "Misafire çay veya kahve ikramı sıcak karşılamanın temel göstergesidir; reddetmek hoş karşılanmayabilir.": "Oferecer chá ou café turco é o gesto de hospitalidade por excelência; recusar de cara pode soar indelicado.",
  "Offering tea or Turkish coffee is the quintessential gesture of hospitality; declining directly may seem impolite.": "Oferecer chá ou café turco é o gesto de hospitalidade por excelência; recusar de cara pode soar indelicado.",
  "Büyüklere saygı esastır; toplu taşımada yaşlılara ve hamilelere yer verilir.": "Respeito profundo pelos mais velhos; espera-se que você ceda o lugar no transporte público.",
