  "Akdeniz sıcaklığı ile Doğu misafirperverliğinin eşsiz sentezi. Aile bağları kuvvetli, çay bahçeleri ve sokak sosyalleşmesi hayatın merkezindedir.": "Uma síntese única do calor mediterrâneo com a hospitalidade oriental. Laços familiares fortes, animados jardins de chá e uma rica vida social nas ruas.",
