  "Nisan - Haziran (İlkbahar) ve Eylül - Kasım (Sonbahar) kültür gezileri için; Haziran - Eylül sahil turizmi için idealdir.": "Abril a junho (primavera) e setembro a novembro (outono) para explorar a cultura; junho a setembro para férias na praia.",
  "April - June (Spring) and September - November (Autumn) for cultural exploration; June - September for coastal beach holidays.": "Abril a junho (primavera) e setembro a novembro (outono) para explorar a cultura; junho a setembro para férias na praia.",
  "İstanbul’da vapurla kıtalararası geçiş yapın; Ege ve Akdeniz kıyılarında araba kiralayarak antik kentleri keşfedin.": "Em Istambul, pegue uma balsa que cruza de um continente para o outro; alugue um carro no litoral do Egeu e do Mediterrâneo para explorar ruínas isoladas.",
  "Take a commuter ferry across continents in Istanbul; rent a car along the Aegean & Mediterranean coasts to explore secluded ruins.": "Em Istambul, pegue uma balsa que cruza de um continente para o outro; alugue um carro no litoral do Egeu e do Mediterrâneo para explorar ruínas isoladas.",
  "Müslüman (~%98, çoğunlukla Sünni ve Alevi), Hristiyan ve Musevi azınlık toplulukları.": "Muçulmanos (~98%, predominantemente sunitas e alevitas), com comunidades históricas cristãs e judaicas.",
  "Muslim (~98%, predominantly Sunni and Alevi), with Christian and Jewish historical communities.": "Muçulmanos (~98%, predominantemente sunitas e alevitas), com comunidades históricas cristãs e judaicas.",
  "Cami ziyaretlerinde omuzlar ve dizler örtülü olmalı, kadınlar baş örtüsü takmalıdır. Girişte ayakkabılar çıkarılır, ibadet edenlerin önünden geçilmez.": "Cubra ombros e joelhos nas mesquitas; mulheres devem usar lenço na cabeça. Tire os sapatos ao entrar e evite passar na frente de quem está rezando.",
  "Cover shoulders and knees in mosques; women must wear a headscarf. Remove shoes upon entering and avoid walking in front of those praying.": "Cubra ombros e joelhos nas mesquitas; mulheres devem usar lenço na cabeça. Tire os sapatos ao entrar e evite passar na frente de quem está rezando.",
