  "Kredi ve banka kartı kullanımı çok yaygındır (%95 temassız). Taksilerde ve küçük bakkallarda nakit TL veya karekod gerekebilir.": "Cartões de crédito e débito são aceitos praticamente em todo lugar (95% por aproximação). Barraquinhas de rua ou táxis em áreas rurais podem exigir dinheiro em TRY.",
  "Credit & debit card acceptance is extremely high (95% contactless). Small street stalls or rural taxis may require cash TRY.": "Cartões de crédito e débito são aceitos praticamente em todo lugar (95% por aproximação). Barraquinhas de rua ou táxis em áreas rurais podem exigir dinheiro em TRY.",
  "İmalat sanayii, turizm, inşaat, tarım ve otomotiv ihracatı temel lokomotiflerdir.": "Indústria, turismo, construção, agricultura e exportação de veículos comerciais.",
  "Manufacturing, tourism, construction, agriculture, and commercial vehicle export.": "Indústria, turismo, construção, agricultura e exportação de veículos comerciais.",
  "Restoranlarda %10-15 bahşiş teamüldür. Faturaya servis ücreti eklenmiş olsa dahi garsona nakit bırakılması takdir edilir.": "É costume deixar 10-15% de gorjeta nas refeições. Mesmo que o serviço venha cobrado na conta, uma pequena gorjeta em dinheiro entregue direto ao garçom é bem-vinda.",
  "10-15% tip is customary in dining. Even if service is charged on the bill, small cash tip directly to server is appreciated.": "É costume deixar 10-15% de gorjeta nas refeições. Mesmo que o serviço venha cobrado na conta, uma pequena gorjeta em dinheiro entregue direto ao garçom é bem-vinda.",
  "Dükkanlara veya kafelere girerken mutlaka \"Bonjour\" (İyi günler) denmelidir; selam vermemek saygısızlık kabul edilir.": "Sempre cumprimente os comerciantes com \"Bonjour\" ao entrar; não cumprimentar é considerado falta de educação.",
  "Always greet shopkeepers with \"Bonjour\" upon entering; failing to greet is considered rude.": "Sempre cumprimente os comerciantes com \"Bonjour\" ao entrar; não cumprimentar é considerado falta de educação.",
  "Yemek yemek bir sanattır; hızlıca atıştırmak yerine yemeğin tadını çıkararak masada uzun süre oturulur.": "Comer é uma arte; as refeições são feitas sem pressa e celebradas em volta da mesa.",
  "Dining is an art form; meals are unhurried and celebrated around the table.": "Comer é uma arte; as refeições são feitas sem pressa e celebradas em volta da mesa.",
  "Resmi hitapta \"Vous\" (Siz) kullanılır; samimi \"Tu\" (Sen) yalnızca yakın arkadaşlar arasındadır.": "Use o educado \"vous\" em vez do informal \"tu\", a menos que seja convidado a fazer isso.",
  "Use polite \"Vous\" rather than informal \"Tu\" unless invited to do so.": "Use o educado \"vous\" em vez do informal \"tu\", a menos que seja convidado a fazer isso.",
  "Sokakta yüksek sesle bağırmak veya aşırı taşkın davranışlar hoş karşılanmaz.": "Falar alto em lugares públicos ou causar tumulto é malvisto.",
  "Speaking loudly in public spaces or being disruptive is frowned upon.": "Falar alto em lugares públicos ou causar tumulto é malvisto.",
