  "Nisan - Haziran ve Eylül - Ekim arası Paris ve şarap bölgeleri için; Temmuz - Ağustos Akdeniz sahilleri için en popülerdir.": "Abril a junho e setembro a outubro para Paris e as regiões vinícolas; julho a agosto para as praias do Mediterrâneo.",
  "April - June and September - October for Paris and wine country; July - August for Mediterranean beaches.": "Abril a junho e setembro a outubro para Paris e as regiões vinícolas; julho a agosto para as praias do Mediterrâneo.",
  "TGV (hızlı tren) ile Paris’ten Lyon, Marsilya ve Bordeaux’ya 2 saatte ulaşın; metro için Île-de-France Navigo Pass kullanın.": "Use os trens de alta velocidade TGV entre as cidades; compre um passe de transporte de Île-de-France para o metrô de Paris.",
  "Use high-speed TGV trains across cities; get an Île-de-France transport pass for Paris Metro.": "Use os trens de alta velocidade TGV entre as cidades; compre um passe de transporte de Île-de-France para o metrô de Paris.",
  "Katolik Hristiyan (~%47), Seküler / Dinsiz (~%40), Müslüman (~%9), Musevi (~%1).": "Cristãos católicos (~47%), sem religião/laicos (~40%), muçulmanos (~9%), judeus (~1%).",
  "Catholic Christian (~47%), Secular / Non-religious (~40%), Muslim (~9%), Jewish (~1%).": "Cristãos católicos (~47%), sem religião/laicos (~40%), muçulmanos (~9%), judeus (~1%).",
  "Laiklik (Laïcité) devletin temel ilkesidir. Katedrallerde sessizlik korunmalı, şapkalar çıkarılmalıdır.": "O laicismo do Estado (laïcité) está na Constituição. Mantenha silêncio e use roupas adequadas nas catedrais históricas.",
  "State secularism (Laïcité) is constitutional. Maintain silence and respectful attire in historic cathedrals.": "O laicismo do Estado (laïcité) está na Constituição. Mantenha silêncio e use roupas adequadas nas catedrais históricas.",
