  "Fransızca (Français). Şehirlerde ve genç nesilde İngilizce bilinir ancak önce Fransızca selamlaşmak büyük saygı görür.": "Francês (français). Em hotéis e cidades se fala inglês, mas começar com \"Bonjour\" muda tudo.",
  "French (Français). English is spoken in hotels and cities, but starting with \"Bonjour\" changes everything.": "Francês (français). Em hotéis e cidades se fala inglês, mas começar com \"Bonjour\" muda tudo.",
  "Turizm ve otelcilikte iyi; yerel mekanlarda birkaç kelime Fransızca takdirle karşılanır.": "Moderado a alto no turismo e hotelaria; tentar algumas frases básicas em francês é muito bem-visto.",
