  "Temassız kart ve Apple Pay kullanımı %98 oranındadır. Kafelerde tek bir kahve için dahi kart geçerlidir.": "Quase não se usa dinheiro vivo; cartões por aproximação e Apple Pay são aceitos praticamente em todo lugar, até para compras de 1 € na padaria.",
  "Extremely cashless; contactless card and Apple Pay accepted virtually everywhere down to €1 bakery items.": "Quase não se usa dinheiro vivo; cartões por aproximação e Apple Pay são aceitos praticamente em todo lugar, até para compras de 1 € na padaria.",
  "Dünyanın en çok ziyaret edilen turizm ülkesi; lüks tüketim, tarım, havacılık ve finans.": "Destino turístico número um do mundo em chegadas; marcas de luxo, setor aeroespacial, agricultura e bancos.",
  "World’s #1 tourist destination by arrivals; luxury brands, aerospace, agriculture, and banking.": "Destino turístico número um do mundo em chegadas; marcas de luxo, setor aeroespacial, agricultura e bancos.",
  "Faturaya %15 servis ücreti (\"service compris\") dahildir. İyi hizmet için masaya 1-2 € bozuk para bırakmak nezakettir.": "O serviço está incluído por lei na conta (\"service compris\"). É costume deixar de 1 a 3 € em moedas por um atendimento simpático.",
  "Service is legally included on the bill (\"service compris\"). Leaving €1-3 in coins for pleasant service is customary.": "O serviço está incluído por lei na conta (\"service compris\"). É costume deixar de 1 a 3 € em moedas por um atendimento simpático.",
  "Öğleden sonra saat 11:00’den sonra Cappuccino SİPARİŞ EDİLMEZ; İtalyanlar sütlü kahveyi sadece sabah içer, sonrasında sadece Espresso (Caffè) içilir.": "Nunca peça cappuccino depois das 11h; café com leite é só para o café da manhã. Depois do almoço ou do jantar, tome espresso.",
  "Never order a Cappuccino after 11:00 AM; milk-based coffees are strictly for breakfast. Drink Espresso after lunch or dinner.": "Nunca peça cappuccino depois das 11h; café com leite é só para o café da manhã. Depois do almoço ou do jantar, tome espresso.",
  "Pizzayı ketçap veya mayonezle yemek ya da spagettiyi bıçakla kesmek hakaret sayılır.": "Nunca corte o espaguete com faca nem peça ketchup na pizza; isso é considerado um crime culinário.",
  "Never cut spaghetti with a knife or ask for ketchup on pizza; it is considered a culinary crime.": "Nunca corte o espaguete com faca nem peça ketchup na pizza; isso é considerado um crime culinário.",
