  "Kart ve temassız ödeme kanunen tüm işletmelerde zorunludur. Ancak espresso için 1-2 € bozuk para bulundurmak pratiktir.": "Cartões e pagamento por aproximação são aceitos por lei em todo lugar. Vale ter moedas de 1 ou 2 € à mão para um cafezinho rápido no balcão.",
  "Cards and contactless legally accepted everywhere. Having €1-2 coins handy for quick coffee bars is convenient.": "Cartões e pagamento por aproximação são aceitos por lei em todo lugar. Vale ter moedas de 1 ou 2 € à mão para um cafezinho rápido no balcão.",
  "Euro Bölgesi’nin 3. büyük ekonomisi; lüks üretim, otomotiv, turizm ve tarımsal gıda ihracatı.": "A terceira maior economia da zona do euro; indústria avançada, artigos de luxo, turismo e exportação agroalimentar.",
  "Eurozone’s 3rd largest economy; advanced manufacturing, luxury goods, tourism, and agri-food exports.": "A terceira maior economia da zona do euro; indústria avançada, artigos de luxo, turismo e exportação agroalimentar.",
  "Bahşiş zorunlu değildir; faturada \"Coperto\" (kuver/ekmek ücreti 1-3 €) bulunabilir. Memnuniyet için masaya 1-2 € bozukluk bırakılır.": "Gorjeta não é esperada; as contas costumam incluir o \"coperto\" (taxa de pão/serviço, 1-3 €). Arredondar com moedas é uma gentileza.",
  "Tipping is not expected; bills often include \"Coperto\" (cover charge for bread/service, €1-3). Rounding up with coins is polite.": "Gorjeta não é esperada; as contas costumam incluir o \"coperto\" (taxa de pão/serviço, 1-3 €). Arredondar com moedas é uma gentileza.",
  "Akşam yemekleri çok geç yenir; restoranlar genellikle 20:30 veya 21:00’den önce akşam yemeği servisi açmaz.": "O jantar é bem tarde; os restaurantes raramente abrem para o jantar antes das 20h30 ou 21h.",
  "Dinner is eaten very late; restaurants rarely open for dinner before 8:30 or 9:00 PM.": "O jantar é bem tarde; os restaurantes raramente abrem para o jantar antes das 20h30 ou 21h.",
  "Öğleden sonra 14:00 - 17:00 arası \"Siesta\" zamanıdır; küçük dükkanlar kapanabilir.": "A siesta da tarde (das 14h às 17h) ainda é respeitada nas pequenas lojas familiares das regiões do sul.",
  "Afternoon Siesta (2:00 - 5:00 PM) is still observed by smaller family shops in southern regions.": "A siesta da tarde (das 14h às 17h) ainda é respeitada nas pequenas lojas familiares das regiões do sul.",
  "Barlarda sosyalleşmek ve tapas paylaşmak hayatın merkezindedir.": "A vida social gira em torno de ir de bar em bar dividindo tapas com os amigos.",
