  "Kasım - Mart ayları arası güneşli ve 25-28°C sıcaklıkla en mükemmel zamandır. Yaz aylarında sıcaklık 45°C’yi bulur.": "De novembro a março é o período ideal, ensolarado e com temperaturas agradáveis de 25-28 °C. No verão, os termômetros podem chegar a 45 °C.",
  "November - March offers perfect beach and desert weather (25°C). Avoid intense summer heat (45°C+).": "De novembro a março é o período ideal, ensolarado e com temperaturas agradáveis de 25-28 °C. No verão, os termômetros podem chegar a 45 °C.",
  "Dubai Metrosu sürücüsüzdür ve çok pratiktir; taksiler ve Careem/Uber uygulamaları oldukça yaygın ve güvenilirdir.": "O metrô de Dubai é totalmente automatizado e muito prático; táxis e os aplicativos Careem e Uber estão por toda parte e são confiáveis.",
  "Use the automated Dubai Metro; Careem and public taxis are modern and reliable.": "O metrô de Dubai é totalmente automatizado e muito prático; táxis e os aplicativos Careem e Uber estão por toda parte e são confiáveis.",
