  "Teşekkürler": "Fundado em 1971 pela união de sete emirados sob a liderança do xeque Zayed bin Sultan Al Nahyan. Em apenas meio século, passou da pesca de pérolas e do nomadismo beduíno a um epicentro global de aviação, comércio e tecnologia.",
  "1971’de Şeyh Zayed bin Sultan Al Nahyan önderliğinde 7 emirliğin birleşmesiyle kuruldu. İnci dalgıçlığı ve bedevi çöl yaşamından yarım yüzyılda küresel havacılık, ticaret ve teknoloji üssüne dönüştü.": "Fundado em 1971 pela união de sete emirados sob a liderança do xeque Zayed bin Sultan Al Nahyan. Em apenas meio século, passou da pesca de pérolas e do nomadismo beduíno a um epicentro global de aviação, comércio e tecnologia.",
  "Formed in 1971 by the union of seven emirates led by Sheikh Zayed. Transformed within 50 years from pearl-diving sands into a global trading, aviation, and tech nexus.": "Fundado em 1971 com a união de sete emirados liderados pelo xeque Zayed. Em cinquenta anos, passou de areias de coletores de pérolas a um polo global de comércio, aviação e tecnologia de ponta.",
