  "Neredeyse tamamen nakitsiz (%99 Apple Pay ve Kart). Taksilerde ve sokak satıcılarında bile kart geçerlidir.": "Economia praticamente sem dinheiro vivo (99 % dos pagamentos com cartão ou Apple Pay). Aceitam cartão até em táxis e pequenas barracas de rua.",
  "Completely cashless; contactless Apple Pay, Google Pay, and cards accepted universally.": "Economia praticamente sem dinheiro vivo (99 % dos pagamentos com cartão ou Apple Pay). Aceitam cartão até em táxis e pequenas barracas de rua.",
  "Petrol ve doğalgaz, küresel ticaret ve limanlar, turizm, gayrimenkul ve finans.": "Petróleo e gás natural, comércio marítimo e portos internacionais, turismo, setor imobiliário e finanças.",
  "Hydrocarbons, international trade, aviation, real estate, and finance.": "Petróleo e gás natural, comércio marítimo e portos internacionais, turismo, setor imobiliário e finanças.",
  "Restoranlarda %10-15 bahşiş teamüldür; faturaya ek servis ücreti olsa da garsona doğrudan bırakılır.": "É comum deixar 10-15 % de gorjeta nos restaurantes; mesmo que a conta inclua taxa de serviço, costuma-se entregar em mãos ao garçom.",
  "10-15% tip is customary in dining. Valets and delivery drivers usually receive 5-10 AED.": "É comum deixar 10-15 % de gorjeta nos restaurantes; mesmo que a conta inclua taxa de serviço, costuma-se entregar em mãos ao garçom.",
  "Yerel halk son derece sıcak ve esprilidir (\"İbn el-Beled\" esprili Mısır halk kültürü).": "Os moradores são extremamente calorosos e hospitaleiros, famosos pelo senso de humor afiado (o espírito popular «Ibn el-Balad»).",
  "Locals are exceptionally warm and famous for their quick humor across the Arab world.": "Os moradores são extremamente calorosos e hospitaleiros, famosos pelo senso de humor afiado (o espírito popular «Ibn el-Balad»).",
  "Pazarlarda (Han el-Halili) pazarlık yapmak adettir; ilk söylenen fiyatın yarısından başlanabilir.": "Nos bazares tradicionais, como o Khan el-Khalili, pechinchar é praticamente obrigatório; costuma-se começar oferecendo metade do preço inicial.",
  "Bargaining in traditional bazaars (Khan el-Khalili) is an expected social dance.": "Nos bazares tradicionais, como o Khan el-Khalili, pechinchar é praticamente obrigatório; costuma-se começar oferecendo metade do preço inicial.",
  "Bahşiş (Baksheesh) kültürü günlük hayatın her alanında beklentidir; küçük bozukluklar hazır tutulmalıdır.": "A cultura do «baksheesh» (gorjeta) está presente em quase todos os serviços do dia a dia; tenha sempre notas pequenas de libra egípcia.",
  "\"Baksheesh\" (tipping) is deeply woven into daily services; carry small Egyptian pounds.": "A cultura do «baksheesh» (gorjeta) está presente em quase todos os serviços do dia a dia; tenha sempre notas pequenas de libra egípcia.",
  "Camilerde ayakkabılar çıkarılır ve kadınlar baş örtüsü takar.": "Nas mesquitas, é obrigatório tirar os sapatos, e as mulheres devem cobrir a cabeça.",
  "Remove shoes and dress conservatively in historic mosques.": "Nas mesquitas, é obrigatório tirar os sapatos, e as mulheres devem cobrir a cabeça.",
