  "Firavunlar çağı, piramitler ve hiyerogliflerle 5000 yılı aşkın insanlık tarihinin başlangıcı. İskenderiye, Roma, İslam fetihleri ve Memlükler sonrası modern Mısır, Arap dünyasının kültürel kalbidir.": "Mais de 5.000 anos de história documentada, desde os faraós, as pirâmides e os hieróglifos. Depois dos períodos ptolomaico, romano, islâmico e mameluco, o Egito moderno é o coração cultural do mundo árabe.",
  "Spanning over 5,000 years of recorded civilization from Pharaohs and Pyramids. Ruled by Ptolemaic dynasties, Romans, and Mamluks, today the cultural anchor of the Arab world.": "Mais de 5.000 anos de história documentada, desde os faraós, as pirâmides e os hieróglifos. Depois dos períodos ptolomaico, romano, islâmico e mameluco, o Egito moderno é o coração cultural do mundo árabe.",
