  "Tipping is institutionalized. 18-22% in restaurants, 15-20% for taxis, and $2-5 for luggage/valet.": "A cultura da gorjeta é muito forte: 18-22% em restaurantes, 15-20% em táxis e US$ 2-5 por mala ou para o manobrista.",
