  "Tiflis ve Batum’da temassız kartlar ve Apple Pay çok yaygındır; dağ köyleri ve pazarlar için nakit Gürcü Larisi (GEL) gereklidir.": "Em Tbilisi e Batumi, cartões por aproximação e Apple Pay são muito comuns; para vilarejos de montanha e mercados, é preciso levar lari georgiano (GEL) em dinheiro.",
  "Contactless cards and Apple Pay universal in cities; carry cash GEL for mountain villages.": "Em Tbilisi e Batumi, cartões por aproximação e Apple Pay são muito comuns; para vilarejos de montanha e mercados, é preciso levar lari georgiano (GEL) em dinheiro.",
