  "Restoranlarda genellikle %10-18 servis ücreti faturaya eklenir. Eklenmemişse %10 bahşiş bırakılır.": "Nos restaurantes, costuma-se acrescentar entre 10% e 18% de taxa de serviço à conta. Se não estiver incluída, deixe 10% de gorjeta.",
  "A 10-18% service fee is often added to restaurant bills. Otherwise, tip 10%.": "Nos restaurantes, costuma-se acrescentar entre 10% e 18% de taxa de serviço à conta. Se não estiver incluída, deixe 10% de gorjeta.",
  "Kahve aceleye getirilmez; Boşnak kahvesi lokum ve sigara eşliğinde saatlerce yudumlanır.": "O café não se toma com pressa: o café bósnio é saboreado devagar, durante horas, acompanhado de um lokum (delícia turca).",
  "Coffee is never rushed; Bosnian coffee is savored slowly for hours with Turkish delight.": "O café não se toma com pressa: o café bósnio é saboreado devagar, durante horas, acompanhado de um lokum (delícia turca).",
  "Savaş ve etnik siyaset gibi hassas konular yabancılarla hemen açılmaz.": "Evite puxar assuntos delicados sobre a guerra dos anos 1990 ou a política étnica com desconhecidos.",
