  "Mayıs - Ekim (Şehir gezileri ve kanyon raftingi için); Aralık - Mart (Jahorina ve Bjelašnica kayak merkezleri için).": "De maio a outubro para passeios culturais e rafting; de dezembro a março para esquiar em Jahorina e Bjelašnica.",
  "May - October for cultural tours and rafting; December - March for Jahorina ski resorts.": "De maio a outubro para passeios culturais e rafting; de dezembro a março para esquiar em Jahorina e Bjelašnica.",
  "Türk vatandaşları için 90 güne kadar vizesizdir. Saraybosna-Mostar arasındaki tren yolculuğu Avrupa’nın en güzel manzaralı tren rotalarından biridir.": "Isenção de visto de até 90 dias para cidadãos turcos. A rota de trem entre Sarajevo e Mostar é uma das mais panorâmicas e bonitas da Europa.",
  "Visa-free for Turkish citizens. The Sarajevo-Mostar scenic passenger train is ranked among Europe’s most beautiful rail rides.": "Isenção de visto de até 90 dias para cidadãos turcos. A rota de trem entre Sarajevo e Mostar é uma das mais panorâmicas e bonitas da Europa.",
  "Müslüman Boşnaklar (~%51), Ortodoks Sırplar (~%31), Katolik Hırvatlar (~%15). Çok dinli tarihi mozaik.": "Bósnios muçulmanos (~51%), sérvios ortodoxos (~31%), croatas católicos (~15%). Mosaico multirreligioso histórico.",
  "Muslim Bosniaks (~51%), Orthodox Christian Serbs (~31%), Roman Catholic Croats (~15%). Historic multifaith mosaic.": "Bósnios muçulmanos (~51%), sérvios ortodoxos (~31%), croatas católicos (~15%). Mosaico multirreligioso histórico.",
  "Cami, kilise ve sinagogların yan yana bulunduğu \"Avrupa’nın Kudüs’ü\" olarak anılır; tüm ibadethanelere saygılı kıyafetle girilir.": "Conhecida como a «Jerusalém da Europa» pela convivência de mesquitas, igrejas e sinagogas; exige-se roupa respeitosa nos templos.",
