  "Para birimi Bosna Konvertibl Markı’dır (BAM - Euro’ya 1 EUR = 1.95583 BAM sabit kurla bağlıdır). Nakit para hala çok önemlidir; restoran ve çarşılarda nakit BAM bulundurun.": "Geração de energia hidrelétrica",
  "Currency is Convertible Mark (BAM, pegged to EUR at 1 EUR = 1.95583 BAM). Cash is essential for cafes, bazaars, and taxis.": "A moeda é o marco conversível (BAM, com câmbio fixo em relação ao euro: 1 EUR = 1,95583 BAM). Dinheiro vivo é indispensável em cafés, bazares e táxis.",
  "Turizm gelirleri, enerji üretimi, madencilik, ahşap imalat sanayii ve yurtdışında yaşayan Boşnakların işçi dövizleri.": "Receitas do turismo, exportação de energia, mineração, indústria madeireira e remessas da diáspora.",
