  "Restoran ve kafelerde hesabı yukarı yuvarlamak veya %10 bahşiş bırakmak çok yaygındır.": "Em restaurantes e cafés, é muito comum arredondar a conta ou deixar 10% de gorjeta.",
  "Tipping 10% or rounding up the bill is customary and appreciated.": "Em restaurantes e cafés, é muito comum arredondar a conta ou deixar 10% de gorjeta.",
  "Selamlaşırken eller göğüs hizasında birleştirilip baş eğilir (Wai selamı).": "Ao cumprimentar, junte as palmas das mãos na altura do peito e incline levemente a cabeça (a saudação 'Wai').",
  "Greet with a respectful \"Wai\" (palms pressed together with a slight bow).": "Ao cumprimentar, junte as palmas das mãos na altura do peito e incline levemente a cabeça (a saudação 'Wai').",
  "Kraliyet ailesine ve Kral portrelerine en üst düzeyde saygı gösterilir; eleştiri yasal suçtur (Lèse-majesté).": "Exige-se o máximo respeito à família real e aos retratos do Rei; críticas são crime grave previsto em lei (lesa-majestade).",
  "Deep reverence for the Royal Family is mandatory; disrespect is legally penalized.": "Exige-se o máximo respeito à família real e aos retratos do Rei; críticas são crime grave previsto em lei (lesa-majestade).",
  "Baş vücudun en kutsal yeri sayılır; çocukların veya yetişkinlerin başına asla dokunulmaz.": "A cabeça é considerada a parte mais sagrada do corpo; nunca toque na cabeça de crianças nem de adultos.",
  "The head is considered sacred; never touch anyone’s head.": "A cabeça é considerada a parte mais sagrada do corpo; nunca toque na cabeça de crianças nem de adultos.",
  "Ayaklar en kirli yer kabul edilir; birini veya Buda heykellerini ayakla işaret etmek büyük saygısızlıktır.": "Os pés são considerados a parte mais baixa e impura; apontar os pés para pessoas ou estátuas de Buda é uma grave falta de respeito.",
  "Feet are seen as lowly; never point feet towards monks, Buddha statues, or people.": "Os pés são considerados a parte mais baixa e impura; apontar os pés para pessoas ou estátuas de Buda é uma grave falta de respeito.",
