  "Para birimi Tayland Bahtı’dır (THB). Sokak lezzetleri, pazarlar ve tuk-tuklar için nakit para zorunludur; alışveriş merkezlerinde kart geçerlidir.": "A moeda é o baht tailandês (THB). Dinheiro vivo é indispensável para comida de rua, mercados noturnos e tuk-tuks; nos shoppings, aceitam cartão.",
  "Currency is Thai Baht (THB). Cash is vital for street food and night markets; cards accepted in malls.": "A moeda é o baht tailandês (THB). Dinheiro vivo é indispensável para comida de rua, mercados noturnos e tuk-tuks; nos shoppings, aceitam cartão.",
  "Turizm, otomotiv montajı, elektronik üretimi ve tarımsal gıda ihracatı.": "Turismo, montagem de veículos, manufatura eletrônica e exportação agroalimentar.",
  "Tourism, automotive assembly, electronics manufacturing, and agriculture.": "Turismo, montagem de veículos, manufatura eletrônica e exportação agroalimentar.",
  "Geleneksel olarak bahşiş kültürü yoktur ancak turizmde masada 20-50 THB bırakmak veya %10 eklemek çok takdir edilir.": "Tradicionalmente não existe cultura de gorjeta, mas nas áreas turísticas deixar entre 20 e 50 THB, ou 10% em restaurantes com serviço à mesa, é muito bem-visto.",
  "Not historically customary, but leaving 20-50 THB or 10% in sit-down restaurants is appreciated.": "Tradicionalmente não existe cultura de gorjeta, mas nas áreas turísticas deixar entre 20 e 50 THB, ou 10% em restaurantes com serviço à mesa, é muito bem-visto.",
  "Taarof geleneği: İranlılar nezaketen ödemeyi veya ikramı ilk teklifte geri çevirebilir; her zaman en az iki-üç kez ödemede ısrar edin.": "Tradição do Taarof: por cortesia, os iranianos costumam recusar pagamentos ou presentes na primeira vez; sempre insista em pagar pelo menos duas ou três vezes.",
  "The art of Taarof: Locals politely refuse payments or gifts initially; always insist at least two to three times.": "Tradição do Taarof: por cortesia, os iranianos costumam recusar pagamentos ou presentes na primeira vez; sempre insista em pagar pelo menos duas ou três vezes.",
  "Evlere ve kutsal türbelere girerken ayakkabılar kesinlikle çıkarılır.": "É obrigatório tirar os sapatos antes de entrar em casas particulares e santuários religiosos.",
  "Shoes must always be removed before entering private homes and religious shrines.": "É obrigatório tirar os sapatos antes de entrar em casas particulares e santuários religiosos.",
  "Kamuya açık alanlarda kılık kıyafet kurallarına (kadınlar için başörtüsü/şal ve dökümlü giysiler, erkekler için uzun pantolon) uyulur.": "Em locais públicos, respeite os códigos de vestimenta (lenço/véu e roupas largas para mulheres, calça comprida para homens).",
  "Dress modestly in public spaces (headscarves/tunics for women, long trousers for men).": "Em locais públicos, respeite os códigos de vestimenta (lenço/véu e roupas largas para mulheres, calça comprida para homens).",
  "Fotoğraf çekerken devlet daireleri, askeri bölgeler ve köprülerden kesinlikle uzak durulmalıdır.": "É terminantemente proibido fotografar prédios do governo, instalações militares e pontes de infraestrutura.",
  "Never photograph government buildings, military sites, or infrastructure bridges.": "É terminantemente proibido fotografar prédios do governo, instalações militares e pontes de infraestrutura.",
