  "Nowruz (March 21 - Persian New Year and Spring Equinox)": "Nowruz (21 de março - Ano-Novo persa e festa da primavera)",
  "Şeb-i Yelda (Kış Ekinoksu - Nar, karpuz ve Hafız şiirleriyle kutlanan en uzun gece)": "Shab-e Yalda (solstício de inverno - a noite mais longa, celebrada com romãs, melancia e poesia de Hafez)",
  "Shab-e Yalda (Winter Solstice - longest night celebrated with pomegranates & Hafez poetry)": "Shab-e Yalda (solstício de inverno - a noite mais longa, celebrada com romãs, melancia e poesia de Hafez)",
  "Çehârşenbe Sûrî (Yeni yıl öncesi son çarşamba ateş üzerinden atlama festivali)": "Chaharshanbe Suri (festa do fogo, com saltos sobre fogueiras na última quarta-feira antes do Nowruz)",
  "Chaharshanbe Suri (Festival of Fire jumping prior to Nowruz)": "Chaharshanbe Suri (festa do fogo, com saltos sobre fogueiras na última quarta-feira antes do Nowruz)",
  "Aşure ve Tasua (Muharrem anma törenleri ve geleneksel taziye tiyatrosu)": "Tasu'a e Ashura (comemorações sagradas e encenações teatrais tradicionais de Ta'ziyeh)",
  "Tasu'a and Ashura (Sacred commemorations and Ta'ziyeh theatrical traditions)": "Tasu'a e Ashura (comemorações sagradas e encenações teatrais tradicionais de Ta'ziyeh)",
  "İran toplumu dünyanın en sıcak ve misafirperver halklarındandır. Akşamları serinlikte parklarda aile boyu piknik yapmak, çayhanelerde nane çayı ve nargile eşliğinde sohbet etmek, Hafız ve Sadi şiirleri okumak günlük yaşamın ruhunu oluşturur.": "A sociedade iraniana é uma das mais calorosas e hospitaleiras do mundo. Os piqueniques noturnos em família nos parques, as conversas com chá de açafrão em casas de chá históricas e a recitação de poesia de Hafez e Saadi definem a alma do dia a dia.",
  "Iranian society is renowned for supreme hospitality. Evening picnics in public gardens, sipping saffron tea at historic teahouses, and reciting classical Persian poetry define the cultural spirit.": "A sociedade iraniana é uma das mais calorosas e hospitaleiras do mundo. Os piqueniques noturnos em família nos parques, as conversas com chá de açafrão em casas de chá históricas e a recitação de poesia de Hafez e Saadi definem a alma do dia a dia.",
  "Persepolis & Nakş-ı Rüstem Antik Kaya Mezarları (Şiraz - Ahameniş Başkenti)": "Ruínas de Persépolis e túmulos reais de Naqsh-e Rustam (Shiraz - capital aquemênida)",
  "Persepolis Ruins & Naqsh-e Rustam Imperial Tombs (Shiraz - Achaemenid Capital)": "Ruínas de Persépolis e túmulos reais de Naqsh-e Rustam (Shiraz - capital aquemênida)",
  "Nakş-ı Cihan Meydanı, Şeyh Lütfullah Camii & Ali Kapu Sarayı (İsfahan - UNESCO)": "Praça Naqsh-e Jahan, Mesquita do Xeque Lotfollah e Palácio de Ali Qapu (Isfahan - UNESCO)",
  "Naqsh-e Jahan Square, Sheikh Lotfollah Mosque & Ali Qapu Palace (Isfahan - UNESCO)": "Praça Naqsh-e Jahan, Mesquita do Xeque Lotfollah e Palácio de Ali Qapu (Isfahan - UNESCO)",
  "Nasır el-Mülk Pembe Camii & Hafız Türbesi (Şiraz)": "Mesquita Rosa de Nasir al-Mulk e Mausoléu de Hafez (Shiraz)",
