  "Yezd Tarihi Kerpiç Şehri, Sessizlik Kuleleri & Zerdüşt Ateşgahı": "Cidade histórica de adobe de Yazd, Torres do Silêncio e Templo do Fogo zoroastrista",
  "Historic Mud-brick City of Yazd & Zoroastrian Fire Temple": "Cidade histórica de adobe de Yazd, Torres do Silêncio e Templo do Fogo zoroastrista",
  "Tebriz Tarihi Kapalı Çarşısı (UNESCO - Dünyanın en büyük kubbeli çarşı kompleksi)": "Bazar histórico de Tabriz (UNESCO - o maior complexo comercial coberto do mundo)",
  "Tabriz Historic Bazaar Complex (UNESCO)": "Bazar histórico de Tabriz (UNESCO - o maior complexo comercial coberto do mundo)",
  "Mart - Mayıs (İlkbahar çiçekleri ve ılıman hava) ile Eylül - Kasım (Altın sonbahar) seyahat için en ideal dönemlerdir.": "De março a maio (flores da primavera e clima ameno) e de setembro a novembro (outono dourado) são as melhores épocas para viajar.",
  "March - May (Spring blossoms and pleasant weather) and September - November (Golden autumn) are the premier seasons.": "De março a maio (flores da primavera e clima ameno) e de setembro a novembro (outono dourado) são as melhores épocas para viajar.",
  "Tahran'a indikten sonra İsfahan, Şiraz ve Yezd arasına uzanan \"Klasik Kültür Rotası\"nı konforlu VIP ekspres otobüsler veya tren hatlarıyla keşfedin.": "Depois de desembarcar em Teerã, percorra a lendária «Rota Cultural Clássica», que liga Isfahan, Shiraz e Yazd em confortáveis ônibus VIP ou linhas de trem.",
  "Follow the legendary cultural route linking Tehran, Isfahan, Yazd, and Shiraz using comfortable VIP sleeper coaches or trains.": "Depois de desembarcar em Teerã, percorra a lendária «Rota Cultural Clássica», que liga Isfahan, Shiraz e Yazd em confortáveis ônibus VIP ou linhas de trem.",
  "%98 Müslüman (Ağırlıklı Şii İslam, %5-10 Sünni). Zerdüştlük, Ermeni Hristiyanlığı ve Musevilik anayasa güvencesindeki tarihi inanç topluluklarıdır.": "98% muçulmanos (majoritariamente xiitas, 5-10% sunitas). O zoroastrismo, o cristianismo armênio e o judaísmo são comunidades religiosas históricas protegidas pela Constituição.",
  "98% Muslim (Predominantly Shia, 5-10% Sunni). Zoroastrianism, Armenian Christianity, and Judaism are officially protected ancient faiths.": "98% muçulmanos (majoritariamente xiitas, 5-10% sunitas). O zoroastrismo, o cristianismo armênio e o judaísmo são comunidades religiosas históricas protegidas pela Constituição.",
  "Kutsal türbelerde (İmam Rıza Meşhed, Şah Çerağ Şiraz) kadınların çador giymesi zorunludur (girişte ücretsiz temin edilir). Ülke genelinde omuz ve bacakları örten kıyafetler giyilir.": "Nos santuários sagrados (Imam Reza em Mashhad, Shah Cheragh em Shiraz), as mulheres devem usar chador (fornecido gratuitamente na entrada). Em todo o país, usam-se roupas que cubram os ombros e as pernas.",
  "Women must wear a chador when entering major holy shrines (provided complimentary at entrances). Modest attire covering shoulders and legs is required nationwide.": "Nos santuários sagrados (Imam Reza em Mashhad, Shah Cheragh em Shiraz), as mulheres devem usar chador (fornecido gratuitamente na entrada). Em todo o país, usam-se roupas que cubram os ombros e as pernas.",
  "İmam Rıza Türbesi Kompleksi (Meşhed - Dünyanın en büyük cami kompleksi)": "Complexo do Santuário do Imam Reza (Mashhad - o maior complexo de mesquitas do mundo)",
  "Imam Reza Shrine Complex (Mashhad - Largest mosque complex in the world)": "Complexo do Santuário do Imam Reza (Mashhad - o maior complexo de mesquitas do mundo)",
