  "Farsça (Resmi dil). Azerbaycan Türkçesi, Kürtçe, Gilaki ve Lurca yaygın olarak konuşulur. Turistik otellerde ve genç nüfusta İngilizce bilinir.": "Persa / farsi (oficial). O turco azeri, o curdo, o gilaki e o luri são amplamente falados. O inglês é comum entre os jovens e os funcionários de hotéis.",
  "Persian / Farsi (Official). Azerbaijani Turkish, Kurdish, and Gilaki are widely spoken. English is spoken by youth and hospitality staff.": "Persa / farsi (oficial). O turco azeri, o curdo, o gilaki e o luri são amplamente falados. O inglês é comum entre os jovens e os funcionários de hotéis.",
  "Üniversite mezunları ve turistik esnaf arasında İngilizce iyi düzeydedir; Tebriz ve kuzeybatı genelinde Türkçe anadil gibi konuşulur.": "O inglês é bom entre universitários formados, guias e comerciantes do setor turístico; em Tabriz e no noroeste, o turco é falado como língua materna.",
  "Good among academics, tour guides, and boutique hotels. Turkish is fluently spoken in Tabriz and the northwestern provinces.": "O inglês é bom entre universitários formados, guias e comerciantes do setor turístico; em Tabriz e no noroeste, o turco é falado como língua materna.",
