  "Bunun fiyatı ne kadar?": "Quanto custa isto?",
  "İran (Persia), 2.500 yılı aşkın kesintisiz tarihiyle dünya medeniyetinin temel taşlarındandır. M.Ö. 550'de Büyük Kiros'un tarihteki ilk insan hakları bildirgesi sayılan Kiros Silindiri ile kurduğu Ahameniş İmparatorluğu'ndan Sasani dönemine, İslam Altın Çağı'ndaki tıp ve matematik devriminden Safevilerin İsfahan'daki muhteşem mimari rönesansına kadar uzanan eşsiz bir mirasa sahiptir.": "Quanto custa isto?",
  "Iran (Persia) is one of the foundational cradles of human civilization. From Cyrus the Great founding the Achaemenid Empire in 550 BC with the Cyrus Cylinder (the first charter of human rights), through the Golden Age of science and philosophy to the Safavid architectural glory of Isfahan, Persia shaped world history.": "O Irã (Pérsia) é um dos berços fundamentais da civilização humana. Da fundação do Império Aquemênida por Ciro, o Grande, em 550 a.C., com o Cilindro de Ciro (a primeira declaração de direitos humanos), passando pela Era de Ouro da ciência e da filosofia, até o esplendor arquitetônico safávida de Isfahan, a Pérsia moldou a história universal.",
  "M.Ö. 550: Büyük Kiros tarafından Ahameniş Pers İmparatorluğu'nun kuruluşu ve Persepolis'in inşası.": "550 a.C.: Ciro, o Grande, funda o Império Persa Aquemênida e começa a construção de Persépolis.",
  "550 BC: Cyrus the Great founds the Achaemenid Empire; Persepolis is constructed.": "550 a.C.: Ciro, o Grande, funda o Império Persa Aquemênida e começa a construção de Persépolis.",
  "M.Ö. 330: Büyük İskender seferi; ardından Partlar ve Sasani İmparatorluğu dönemi.": "330 a.C. - 651 d.C.: campanhas de Alexandre, o Grande, seguidas pelas dinastias parta e sassânida.",
  "330 BC - 651 AD: Hellenistic, Parthian, and Sasanian imperial dynasties.": "330 a.C. - 651 d.C.: campanhas de Alexandre, o Grande, seguidas pelas dinastias parta e sassânida.",
  "8.-11. Yüzyıl: İslam Altın Çağı ve Fars Bilim Rönesansı (İbn-i Sina, Harizmi, Ömer Hayyam, Firdevsi).": "Séculos VIII-XI: Era de Ouro do Islã e Renascimento científico e literário persa (Avicena, Al-Khwarizmi, Omar Khayyam, Ferdowsi).",
  "8th–11th Century: Golden Age of Science & Literature (Avicenna, Al-Khwarizmi, Omar Khayyam, Ferdowsi).": "Séculos VIII-XI: Era de Ouro do Islã e Renascimento científico e literário persa (Avicena, Al-Khwarizmi, Omar Khayyam, Ferdowsi).",
  "1501: Safevi Hanedanı ve İsfahan'ın başkent oluşu (\"İsfahan Dünyanın Yarısıdır\").": "1501: a dinastia safávida faz de Isfahan a capital cultural («Isfahan é metade do mundo»).",
  "1501: Safavid Dynasty establishes Isfahan as cultural metropolis (\"Isfahan is half the world\").": "1501: a dinastia safávida faz de Isfahan a capital cultural («Isfahan é metade do mundo»).",
  "1979: İran İslam Devrimi ve modern cumhuriyet dönemi.": "1979: Revolução Islâmica do Irã e início da república soberana moderna.",
  "1979: Iranian Revolution and modern sovereign republic.": "1979: Revolução Islâmica do Irã e início da república soberana moderna.",
