  "DİKKAT: Uluslararası bankacılık yaptırımları sebebiyle yabancı Visa, Mastercard ve uluslararası ATM kartları İran'da ÇALIŞMAZ. Seyahat ederken yanınızda nakit USD veya EUR getirmelisiniz. Şehirlerdeki resmi döviz bürolarında (Sarrafi) bozdurabilir veya turistler için sunulan ön ödemeli MahCard / DaricCard temin ederek yerel POS cihazlarında temassız ödeme yapabilirsiniz. Fiyatlar çarşıda genellikle Tümen (1 Tümen = 10 Riyal) olarak söylenir.": "ATENÇÃO: devido às sanções bancárias internacionais, cartões estrangeiros Visa, Mastercard e cartões bancários internacionais NÃO FUNCIONAM no Irã. É obrigatório levar dinheiro vivo (USD ou EUR) para viajar. Você pode trocá-lo em casas de câmbio oficiais (Sarrafi) ou comprar um cartão de débito pré-pago para turistas (como MahCard ou DaricCard) para pagar no comércio local. Nas lojas, os preços costumam aparecer em tomans (1 toman = 10 riais).",
  "CRITICAL: Due to international banking sanctions, foreign Visa, Mastercard, and international ATM cards DO NOT work in Iran. Travelers must bring cash (USD or EUR). You can exchange cash at official Sarrafi exchange booths or obtain a tourist prepaid debit card (such as MahCard or DaricCard) to tap at local Iranian POS terminals. Iranians quote prices in Toman (1 Toman = 10 Rials).": "ATENÇÃO: devido às sanções bancárias internacionais, cartões estrangeiros Visa, Mastercard e cartões bancários internacionais NÃO FUNCIONAM no Irã. É obrigatório levar dinheiro vivo (USD ou EUR) para viajar. Você pode trocá-lo em casas de câmbio oficiais (Sarrafi) ou comprar um cartão de débito pré-pago para turistas (como MahCard ou DaricCard) para pagar no comércio local. Nas lojas, os preços costumam aparecer em tomans (1 toman = 10 riais).",
  "Petrol ve doğal gaz üretimi, petrokimya endüstrisi, safran ve kuruyemiş ihracatı, madencilik ve el sanatları halıcılık.": "Produção de petróleo e gás natural, indústria petroquímica, exportação de açafrão e frutas secas, mineração e artesanato tradicional de tapetes.",
  "Petroleum and natural gas extraction, petrochemicals, agricultural exports (saffron, pistachios), metallurgy and carpet weaving.": "Produção de petróleo e gás natural, indústria petroquímica, exportação de açafrão e frutas secas, mineração e artesanato tradicional de tapetes.",
  "Restoranlarda bahşiş hesaba dahil edilmez; kaliteli servis için %10 civarında nakit bahşiş beklenir ve takdir edilir. Ayrıca geleneksel nezaket kuralı \"Taarof\" (ilk teklifte ücreti reddetme jesti) ile karşılaşıldığında ısrarla ödeme yapılmalıdır.": "A gorjeta não vem incluída na conta dos restaurantes; é costume, e muito bem-vindo, deixar cerca de 10% em dinheiro por um bom serviço. Lembre-se do ritual de cortesia «Taarof» (em que o comerciante pode recusar o pagamento de início, por gentileza): insista sempre em pagar.",
  "Tipping is not included in restaurant bills; around 10% in cash is customary for good service. Beware of \"Taarof\" (cultural politeness ritual where merchants initially refuse payment)—you should always insist on paying.": "A gorjeta não vem incluída na conta dos restaurantes; é costume, e muito bem-vindo, deixar cerca de 10% em dinheiro por um bom serviço. Lembre-se do ritual de cortesia «Taarof» (em que o comerciante pode recusar o pagamento de início, por gentileza): insista sempre em pagar.",
  "Ultra Ekonomik (600-1100$)": "Ultraeconômico (US$ 600-1100)",
