  "Maaş şartı yok! Yalnızca bankada 500.000 THB (~13.500 $) bakiye gösterimi yeterlidir.": "Sem exigência de salário mensal! Basta comprovar saldo bancário de 500.000 THB (~US$ 13.500).",
  "No monthly salary threshold! Bank balance of 500,000 THB (~$13,500) required.": "Sem exigência de salário mensal! Basta comprovar saldo bancário de 500.000 THB (~US$ 13.500).",
  "5 Yıl Geçerli (Her girişte 180 gün kalış + 180 gün uzatma = Yılda 360 gün!)": "Válido por 5 anos (180 dias por entrada + prorrogação de 180 dias = até 360 dias por ano!)",
