  "DTV e-vizesi online alınır; harç sadece ~10.000 THB (~300 $). Ayrıca Türk pasaportuna 30 gün vizesiz giriş (TDAC ile) hakkı mevcuttur.": "Solicitação online do e-Visa DTV (taxa aproximada de 10.000 THB / ~US$ 300). Além disso, há entrada sem visto por 30 dias.",
  "Online DTV eVisa application (~$300 fee). 30 days visa-free entry (with TDAC) also available.": "Solicitação online do e-Visa DTV (taxa aproximada de 10.000 THB / ~US$ 300). Além disso, há entrada sem visto por 30 dias.",
  "Dünyanın en büyük dijital göçebe komünitesi, ucuz sokak lezzetleri, tapınaklar ve tropik ada yaşamı.": "A maior comunidade de nômades digitais do mundo, comida de rua deliciosa e barata, templos e vida em ilhas tropicais.",
